#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=1L)stop("Provide project.yaml",call.=FALSE)
all<-commandArgs(trailingOnly=FALSE);self<-normalizePath(sub("^--file=","",grep("^--file=",all,value=TRUE)[[1]]),winslash="/");root<-normalizePath(file.path(dirname(self),"../.."),winslash="/");config<-normalizePath(args[[1]],winslash="/");app_env<-new.env(parent=.GlobalEnv);source(file.path(root,"app/shiny/app.R"),local=app_env)
shiny::testServer(app_env$server,{session$setInputs(project_selector=config,open_project=1);session$flushReact();stopifnot(length(preprocessing_selected_samples())==8L);session$setInputs(preprocessing_threads=2,create_hit_file_dry_run=FALSE,create_hit_file_force=FALSE,create_hit_file_keep_going=TRUE,run_all_create_hit_file=1);session$flushReact();stopifnot(jobs$job_is_running());deadline<-Sys.time()+900;while(jobs$job_is_running()&&Sys.time()<deadline){jobs$poll_job();Sys.sleep(.2)};jobs$poll_job();p<-jobs$current_progress();stopifnot(!jobs$job_is_running(),p$status=="success",p$total_items==8L,p$successful_items==7L,p$skipped_items==1L,p$failed_items==0L,p$remaining_items==0L,length(preprocessing_selected_samples())==8L);cat(sprintf("Elapsed seconds: %.3f\nProgress file: %s\n",p$job_elapsed_seconds,jobs$current_job()$progress_file))})
cat("PASS\n")
